CREATE TABLE IF NOT EXISTS bons_livraison_client_commandes (
    bon_livraison_id BIGINT NOT NULL REFERENCES bons_livraison_client(id) ON DELETE CASCADE,
    commande_id BIGINT NOT NULL REFERENCES commandes_client(id) ON DELETE CASCADE,
    PRIMARY KEY (bon_livraison_id, commande_id)
);
CREATE INDEX IF NOT EXISTS idx_bl_client_cmd_bl ON bons_livraison_client_commandes(bon_livraison_id);
CREATE INDEX IF NOT EXISTS idx_bl_client_cmd_cmd ON bons_livraison_client_commandes(commande_id);
